# R101 HOLD: One offline owner preflight for stable v0.6.28 or
# unapproved private v0.6.30. Combines byte-verified original R77 and
# current R90 status without changing the installed Spotify stack,
# agent, autostart, registry, ACL, state, updater or scheduled tasks.
# Only the clipboard receives the final bounded summary. The embedded
# R77 may probe the *already-pinned* Spicetify CLI with -v.
# In hosted scratch mode, R77 is deliberately NOT run against the real
# CI runner; only R90 fixture observation is available.
[CmdletBinding()]
param([string]$HostedFixtureRoot='')
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
$phase='SOURCE_ADMISSION'
$out=New-Object 'System.Collections.Generic.List[string]'
$out.Add('DIAGNOSTIC=SPOTIFY_R101_OWNER_OFFLINE_READONLY_ONEPASS_HOLD')
$out.Add('NETWORK=NO;SPOTIFY_UPDATE=NO;REGISTRY_WRITE=NO;ACL_WRITE=NO;SCHEDULED_TASK_WRITE=NO')
$out.Add('PROCESS_KILL=NO;STARTUP_LINK_WRITE=NO;CONFIG_WRITE=NO;SOURCE_CHANGE=NO')
function Fail([string]$label){throw [InvalidOperationException]::new($label)}
function GitBlob([byte[]]$data){
  $p=[Text.Encoding]::ASCII.GetBytes(('blob '+$data.Length))
  $all=New-Object byte[] ($p.Length+1+$data.Length)
  [Array]::Copy($p,0,$all,0,$p.Length)
  [Array]::Copy($data,0,$all,$p.Length+1,$data.Length)
  $sha=[Security.Cryptography.SHA1]::Create()
  try{return ([BitConverter]::ToString($sha.ComputeHash($all))).Replace('-','').ToLowerInvariant()}
  finally{$sha.Dispose()}
}
function ValueOf([object[]]$lines,[string]$key){
  $pattern=('^'+[regex]::Escape($key)+'=([A-Za-z0-9_.-]{1,115})$')
  $matches=@($lines|Where-Object {[string]$_ -cmatch $pattern})
  if($matches.Count -ne 1){return 'UNKNOWN_OR_DUPLICATE'}
  $line=[string]$matches[0]
  return $line.Substring($key.Length+1)
}
function Status([byte[]]$source,[string]$fixture){
  $script=[ScriptBlock]::Create([Text.Encoding]::UTF8.GetString($source))
  if([string]::IsNullOrEmpty($fixture)){
    return ,@(& $script -Status)
  }
  return ,@(& $script -Status -HostedReadOnlyRoot $fixture)
}
try{
  if([Environment]::OSVersion.Platform -ne [PlatformID]::Win32NT -or
     $PSVersionTable.PSEdition -cne 'Desktop' -or
     $PSVersionTable.PSVersion.Major -ne 5 -or
     -not [Environment]::Is64BitProcess){
    Fail 'R101_WINDOWS_PS51_X64_REQUIRED'
  }
  [byte[]]$r77=[Convert]::FromBase64String('')
  [byte[]]$r90=[Convert]::FromBase64String('')
  if((GitBlob $r77) -cne 'edfdce9429d4a74612b2e6b1d6996ea6bb6fd50e'){
    Fail 'R101_R77_EMBEDDED_GIT_BLOB_MISMATCH'
  }
  if((GitBlob $r90) -cne '52d97d536fe60c3833022e1d3e88a6b26eacddb3'){
    Fail 'R101_R90_EMBEDDED_GIT_BLOB_MISMATCH'
  }
  $out.Add('R101_R77_AND_R90_EXACT_GIT_OBJECTS=PASS')
  $hosted=(-not [string]::IsNullOrWhiteSpace($HostedFixtureRoot))
  if($hosted){
    if($env:GITHUB_ACTIONS -cne 'true' -or
       $env:RUNNER_OS -cne 'Windows' -or
       $env:RUNNER_ENVIRONMENT -cne 'github-hosted' -or
       [string]::IsNullOrWhiteSpace($env:RUNNER_TEMP)){
      Fail 'R101_HOSTED_FIXTURE_NOT_AUTHORIZED'
    }
    $root=[IO.Path]::GetFullPath($HostedFixtureRoot).TrimEnd('\','/')
    $tmp=[IO.Path]::GetFullPath($env:RUNNER_TEMP).TrimEnd('\','/')
    if(-not $root.StartsWith(($tmp+'\'),[StringComparison]::OrdinalIgnoreCase) -or
       [IO.Path]::GetFileName($root) -cne 'SpotifyControl'){
      Fail 'R101_HOSTED_FIXTURE_OUTSIDE_RUNNER_TEMP'
    }
    $out.Add('R101_OWNER_IDENTITY=HOSTED_SYNTHETIC_NO_REAL_OWNER_ATTESTATION')
  }else{
    $owner=[Security.Principal.WindowsIdentity]::GetCurrent()
    if(([Security.Principal.WindowsPrincipal]::new($owner)).IsInRole(
        [Security.Principal.WindowsBuiltInRole]::Administrator)){
      Fail 'R101_OWNER_ELEVATED_NOT_ADMITTED'
    }
    $root=Join-Path ([Environment]::GetFolderPath(
      [Environment+SpecialFolder]::LocalApplicationData)) 'SpotifyControl'
    $out.Add('R101_OWNER_IDENTITY=STANDARD_USER_READONLY')
  }
  $phase='LOCAL_PRECHECK'
  if(-not $hosted){
    # R77 would otherwise call an untrusted binary with -v on an unknown
    # Spicetify source. Require one of its exact official SHA256 pins first.
    $exe=Join-Path $env:LOCALAPPDATA 'spicetify\spicetify.exe'
    $entry=Get-Item -LiteralPath $exe -Force -ErrorAction Stop
    if($entry.PSIsContainer -or
       ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){
      Fail 'R101_OWNER_SPICETIFY_NOT_PLAIN_FILE'
    }
    $cli=(Get-FileHash -LiteralPath $exe -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
    if($cli -cnotin @('85576d80b04ef8922a7f7fe3befbf9fcc56025dfb699b21339b546893742f0c1',
                     '3563f26acd7527adc97e6c19272fa1b48ce976a913625d9804ac57d3c54fb4db')){
      Fail 'R101_UNPINNED_SPICETIFY_CLI_NO_EXECUTION'
    }
    $out.Add('R101_UNPINNED_CLI_EXECUTION=BLOCKED')
  }
  $phase='READONLY_R90_INSTALLED_STATUS'
  $status=@(Status $r90 $(if($hosted){$root}else{''}))
  $statusResult=ValueOf $status 'RESULT'
  if($statusResult -cne 'R93_READONLY_POSTFLIGHT_COLLECTED'){
    Fail 'R101_R90_READONLY_STATUS_HOLD'
  }
  foreach($key in @('R93_MAIN_HASH_CLASS','R93_AGENT_HASH_CLASS',
                    'R93_ADDON_HASH_CLASS','R93_OFFICIAL_BOOTSTRAP_HASH_CLASS',
                    'R93_TRANSACTION','R93_RESIDENT','R93_CLASSIFICATION',
                    'R95_LOGON_ASSESSMENT','R100_R99_GUARDED_LOGON',
                    'R100_LOGON_ASSESSMENT')){
    $out.Add('R101_'+$key+'='+(ValueOf $status $key))
  }
  $mainClass=ValueOf $status 'R93_MAIN_HASH_CLASS'
  $agentClass=ValueOf $status 'R93_AGENT_HASH_CLASS'
  $addonClass=ValueOf $status 'R93_ADDON_HASH_CLASS'
  $bootClass=ValueOf $status 'R93_OFFICIAL_BOOTSTRAP_HASH_CLASS'
  $resident=ValueOf $status 'R93_RESIDENT'
  $guarded=ValueOf $status 'R100_R99_GUARDED_LOGON'
  $stage='HOLD_UNVERIFIED'
  if($mainClass -ceq 'BASELINE' -and $agentClass -ceq 'BASELINE' -and
     $addonClass -ceq 'BASELINE' -and $bootClass -ceq 'BASELINE'){
    $stage='BASELINE_V0628_FILES_EXACT'
  }elseif($mainClass -ceq 'CANDIDATE' -and $agentClass -ceq 'CANDIDATE' -and
          $addonClass -ceq 'BASELINE' -and $bootClass -ceq 'BASELINE'){
    $stage='CANDIDATE_V0630_FILES_EXACT'
  }elseif($mainClass -cin @('BASELINE','CANDIDATE') -and
          $agentClass -cin @('BASELINE','CANDIDATE')){
    $stage='HOLD_MIXED_OR_PARTIAL_VERSION'
  }
  $out.Add('R101_INSTALLED_STAGE='+$stage)
  if($hosted){
    $out.Add('R101_R77_LIVE_OWNER_ADMISSION=NOT_EXECUTED_HOSTED_FIXTURE')
    $out.Add('R101_OVERALL=HOSTED_SCRATCH_STATUS_ONLY_NOT_OWNER_RELEASE_AUTHORITY')
  }else{
    $phase='READONLY_R77_OWNER_SPOTIFY_ACL_COMPATIBILITY'
    $live=@(& ([ScriptBlock]::Create([Text.Encoding]::UTF8.GetString($r77))))
    if((ValueOf $live 'RESULT') -cne 'READONLY_SNAPSHOT_COMPLETE'){
      Fail 'R101_R77_LIVE_OWNER_INSPECTION_HOLD'
    }
    foreach($key in @('OWNER_TOKEN','EXACT_INSTALLED_STACK',
                      'SPOTIFY_VERSION','SPOTIFY_SIGNATURE',
                      'SPICETIFY_CLI_SOURCE_PIN','CURRENT_COMPATIBILITY',
                      'SPOTIFY_PROCESS','RESIDENT_PROCESS_PATH_MATCH',
                      'AGENT_MUTATION_SAVED','SPOTIFY_UPDATE_GUARD_SAVED',
                      'UPDATE_FOLDER_ACL_NOW','SAVED_GUARD_VS_ACL',
                      'ACL_PROOF_LEVEL','OWNER_ENVIRONMENT_PRECHECK')){
      $out.Add('R101_'+$key+'='+(ValueOf $live $key))
    }
    $sound= ((ValueOf $live 'OWNER_TOKEN') -ceq 'STANDARD_USER' -and
             (ValueOf $live 'SPOTIFY_SIGNATURE') -ceq 'VALID_SPOTIFY_AB' -and
             (ValueOf $live 'CURRENT_COMPATIBILITY') -ceq 'OFFICIALLY_SUPPORTED_RANGE' -and
             (ValueOf $live 'SPOTIFY_PROCESS') -ceq 'CLOSED' -and
             (ValueOf $live 'SAVED_GUARD_VS_ACL') -ceq 'SAVED_BLOCKED_MATCHES_LIVE_ACL' -and
             (ValueOf $live 'ACL_PROOF_LEVEL') -ceq 'OWNER_DENY_ACES_ONLY_NOT_ACCESS_CHECK')
    if($stage -ceq 'BASELINE_V0628_FILES_EXACT' -and $sound -and
       (ValueOf $live 'EXACT_INSTALLED_STACK') -ceq 'PASS' -and
       (ValueOf $live 'OWNER_ENVIRONMENT_PRECHECK') -ceq 'READONLY_CONSISTENT_NOT_DEPLOY_AUTHORITY' -and
       $resident -ceq 'ONE_OWNER_PATH_OBSERVED_CODE_NOT_ATTESTED' -and
       $guarded -ceq 'NONE'){
      $out.Add('R101_OVERALL=BASELINE_CONSISTENT_OWNER_REVIEW_NOT_DEPLOY_AUTHORITY')
    }elseif($stage -ceq 'CANDIDATE_V0630_FILES_EXACT' -and $sound -and
       $guarded -ceq 'ONE_OWNED_GUARDED_REGISTERED_NOT_LOGON_PROOF' -and
       (ValueOf $status 'R93_TRANSACTION') -ceq 'COMMITTED_REPORTED_ONLY'){
      $out.Add('R101_OVERALL=CANDIDATE_FILES_GUARDED_LINK_CONSISTENT_REAL_LOGON_UNTESTED')
    }else{
      $out.Add('R101_OVERALL=HOLD_OWNER_ENVIRONMENT_OR_VERSION_NOT_CERTIFIED')
    }
  }
  $out.Add('RESULT=R101_OFFLINE_READONLY_EVIDENCE_COLLECTED')
}catch{
  $reason=[string]$_.Exception.Message
  if($reason -cnotmatch '^R101_[A-Z0-9_]{5,110}$'){
    $reason='R101_UNKNOWN_READONLY_OWNER_OR_SOURCE_HOLD'
  }
  $out.Add('FAILED_PHASE='+$phase)
  $out.Add('HOLD_REASON='+$reason)
  $out.Add('RESULT=R101_READONLY_HOLD_NO_CHANGES')
}finally{
  $out.Add('R101_EFFECTIVE_ACL_ACCESS_CHECK=NOT_TESTED')
  $out.Add('R101_REAL_REBOOT_AND_LOGON=NOT_TESTED')
  $out.Add('R101_DEPLOY_AUTHORIZED=NO;AUTO_REPAIR=NO;AUTO_RETRY=NO')
  $out.Add('RAW_PATHS_SECRETS_AND_PID_OUTPUT=NO')
  try{Set-Clipboard -Value ($out -join [Environment]::NewLine) -ErrorAction Stop}catch{}
  $out|ForEach-Object{Write-Output $_}
}
